  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Berikut ini yang termasuk dalam kategori aset lancar adalah...','[{"key": "A", "text": "Gedung kantor dan tanah"}, {"key": "B", "text": "Mesin pembangkit listrik"}, {"key": "C", "text": "Kas, piutang usaha, dan persediaan"}, {"key": "D", "text": "Investasi jangka panjang pada anak perusahaan"}]'::jsonb,'C','Aset lancar adalah kategori aset yang diharapkan dapat dikonversi menjadi kas, dijual, atau habis dipakai dalam periode satu tahun atau satu siklus operasi normal perusahaan. Kas, piutang usaha (tagihan kepada pelanggan), dan persediaan (seperti suku cadang) adalah contoh utama aset lancar. Gedung dan mesin pembangkit adalah aset tetap, sementara investasi jangka panjang adalah kategori aset tersendiri.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses memindahkan catatan dari jurnal ke buku besar disebut...','[{"key": "A", "text": "Jurnalisasi"}, {"key": "B", "text": "Posting"}, {"key": "C", "text": "Rekonsiliasi"}, {"key": "D", "text": "Auditing"}]'::jsonb,'B','Proses akuntansi dimulai dengan mencatat transaksi di jurnal (jurnalisasi). Setelah itu, setiap entri dalam jurnal tersebut perlu dipindahkan atau diringkas ke dalam akun masing-masing di buku besar (ledger). Proses pemindahan dari jurnal ke buku besar inilah yang disebut sebagai posting. Tujuannya adalah untuk mengelompokkan dampak dari semua transaksi ke dalam akun individual.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari penyusunan neraca saldo (trial balance) adalah...','[{"key": "A", "text": "Untuk menghitung laba bersih perusahaan"}, {"key": "B", "text": "Untuk memastikan total debit sama dengan total kredit"}, {"key": "C", "text": "Untuk melaporkan arus kas perusahaan"}, {"key": "D", "text": "Untuk menganalisis profitabilitas perusahaan"}]'::jsonb,'B','Setelah semua transaksi diposting ke buku besar, neraca saldo (trial balance) disusun sebagai langkah kontrol internal. Neraca saldo adalah daftar semua akun beserta saldo akhirnya (debit atau kredit). Tujuan utamanya adalah untuk memverifikasi secara matematis bahwa total saldo debit di semua akun sama dengan total saldo kredit, sebelum melanjutkan ke tahap penyusunan laporan keuangan.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya pemeliharaan rutin jaringan kabel listrik PLN di suatu area tergolong sebagai...','[{"key": "A", "text": "Biaya bahan baku langsung"}, {"key": "B", "text": "Biaya tenaga kerja langsung"}, {"key": "C", "text": "Biaya overhead operasional"}, {"key": "D", "text": "Biaya administrasi dan umum"}]'::jsonb,'C','Biaya operasional atau overhead adalah semua biaya yang terjadi untuk mendukung proses produksi atau operasi tetapi tidak dapat ditelusuri secara langsung dan mudah ke unit produk tertentu. Biaya pemeliharaan jaringan listrik sangat penting untuk operasi PLN, namun sulit untuk mengalokasikannya ke setiap kilowatt-jam (kWh) listrik yang terjual, sehingga dikelompokkan sebagai biaya overhead.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam metode Activity Based Costing (ABC), biaya dialokasikan ke produk atau jasa berdasarkan...','[{"key": "A", "text": "Volume produksi"}, {"key": "B", "text": "Jumlah jam kerja langsung"}, {"key": "C", "text": "Konsumsi aktivitas"}, {"key": "D", "text": "Keputusan manajer"}]'::jsonb,'C','Activity Based Costing (ABC) adalah metode alokasi biaya overhead yang lebih canggih. Berbeda dengan metode tradisional yang menggunakan pemicu berbasis volume (seperti jam mesin), ABC mengidentifikasi aktivitas-aktivitas utama dalam proses produksi dan mengalokasikan biaya berdasarkan seberapa banyak setiap produk atau jasa mengonsumsi aktivitas tersebut. Hal ini memberikan perhitungan biaya produk yang lebih akurat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan contoh biaya tetap (fixed cost) bagi sebuah unit pembangkit listrik?','[{"key": "A", "text": "Biaya penyusutan gedung pembangkit"}, {"key": "B", "text": "Biaya bahan bakar (batu bara)"}, {"key": "C", "text": "Biaya lembur operator"}, {"key": "D", "text": "Biaya pembelian suku cadang turbin"}]'::jsonb,'A','Biaya tetap adalah biaya yang jumlah totalnya tidak terpengaruh oleh perubahan volume aktivitas atau produksi dalam rentang waktu tertentu. Biaya penyusutan gedung pembangkit dengan metode garis lurus akan memiliki jumlah yang sama setiap periode, terlepas dari berapa banyak listrik yang dihasilkan. Sebaliknya, biaya bahan bakar adalah biaya variabel karena jumlahnya akan naik seiring dengan meningkatnya produksi listrik.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Titik impas (break-even point) tercapai ketika...','[{"key": "A", "text": "Total pendapatan lebih besar dari total biaya"}, {"key": "B", "text": "Laba bersih sama dengan nol"}, {"key": "C", "text": "Total pendapatan sama dengan total biaya variabel"}, {"key": "D", "text": "Total pendapatan sama dengan total biaya tetap"}]'::jsonb,'B','Titik impas atau Break-Even Point (BEP) adalah tingkat penjualan di mana total pendapatan perusahaan sama persis dengan total biayanya (total biaya tetap ditambah total biaya variabel). Pada titik ini, perusahaan tidak mengalami laba maupun rugi. Analisis BEP sangat penting untuk menentukan volume penjualan minimum yang harus dicapai agar tidak merugi.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alokasi biaya departemen pendukung (misalnya, departemen IT) ke departemen produksi (misalnya, unit pembangkit) adalah contoh dari...','[{"key": "A", "text": "Cost tracing"}, {"key": "B", "text": "Job costing"}, {"key": "C", "text": "Product costing"}, {"key": "D", "text": "Cost allocation"}]'::jsonb,'D','Alokasi biaya (cost allocation) adalah proses pembebanan biaya-biaya tidak langsung (indirect costs) ke objek biaya tertentu seperti produk, departemen, atau proyek. Biaya departemen pendukung seperti IT atau HR tidak secara langsung menghasilkan produk, tetapi jasanya dinikmati oleh departemen produksi. Oleh karena itu, biayanya perlu dialokasikan secara wajar ke departemen yang menikmati manfaatnya.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara akuntansi keuangan dan akuntansi manajemen adalah...','[{"key": "A", "text": "Akuntansi keuangan berfokus pada pengguna eksternal, sedangkan akuntansi manajemen untuk internal"}, {"key": "B", "text": "Akuntansi keuangan tidak diatur oleh standar, sedangkan akuntansi manajemen sangat diatur"}, {"key": "C", "text": "Akuntansi manajemen hanya melaporkan data masa lalu"}, {"key": "D", "text": "Akuntansi keuangan lebih fleksibel dalam format laporannya"}]'::jsonb,'A','Ini adalah perbedaan paling fundamental. Akuntansi keuangan menghasilkan laporan (seperti neraca dan laporan laba rugi) yang terstandarisasi sesuai SAK/IFRS untuk pihak luar seperti investor dan kreditur. Sementara itu, akuntansi manajemen menghasilkan laporan yang lebih fleksibel dan detail (seperti anggaran dan analisis biaya) untuk membantu manajer internal dalam membuat keputusan, merencanakan, dan mengendalikan operasi.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Laporan keuangan konsolidasi diperlukan ketika sebuah perusahaan (induk) memiliki...','[{"key": "A", "text": "Hubungan istimewa dengan pemasok"}, {"key": "B", "text": "Pengendalian atas perusahaan lain (anak)"}, {"key": "C", "text": "Piutang yang signifikan pada perusahaan lain"}, {"key": "D", "text": "Transaksi dalam mata uang asing"}]'::jsonb,'B','Laporan keuangan konsolidasi wajib disusun ketika suatu entitas (induk) memiliki pengendalian atas entitas lain (anak). Pengendalian biasanya didefinisikan sebagai kepemilikan lebih dari 50% saham berhak suara, yang memberikan kekuasaan untuk mengatur kebijakan keuangan dan operasional entitas anak demi mendapatkan manfaat dari aktivitasnya.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PT PLN (Persero) sebagai induk perusahaan dari PT Pembangkitan Jawa-Bali (PJB). Laporan keuangan yang menggabungkan keduanya disebut...','[{"key": "A", "text": "Laporan Keuangan Gabungan"}, {"key": "B", "text": "Laporan Keuangan Segmen"}, {"key": "C", "text": "Laporan Keuangan Konsolidasi"}, {"key": "D", "text": "Laporan Keuangan Proforma"}]'::jsonb,'C','Ketika PT PLN (Persero) mengendalikan PT PJB, laporan keuangan keduanya harus digabungkan menjadi satu laporan keuangan tunggal yang disebut laporan keuangan konsolidasi. Laporan ini menyajikan posisi keuangan dan hasil operasi grup perusahaan seolah-olah mereka adalah satu entitas ekonomi tunggal, dengan mengeliminasi transaksi antar perusahaan.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam laporan arus kas, penerimaan kas dari pelanggan diklasifikasikan sebagai aktivitas...','[{"key": "A", "text": "Operasi"}, {"key": "B", "text": "Investasi"}, {"key": "C", "text": "Pendanaan"}, {"key": "D", "text": "Non-kas"}]'::jsonb,'A','Laporan arus kas mengklasifikasikan transaksi kas ke dalam tiga aktivitas: operasi, investasi, dan pendanaan. Aktivitas operasi adalah aktivitas penghasil pendapatan utama perusahaan. Penerimaan kas dari pembayaran tagihan listrik oleh pelanggan merupakan inti dari kegiatan operasional PLN, sehingga masuk dalam kategori aktivitas operasi.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menerbitkan obligasi untuk mendanai pembangunan gardu induk baru. Arus kas dari penerbitan obligasi ini dilaporkan dalam aktivitas...','[{"key": "A", "text": "Operasi"}, {"key": "B", "text": "Investasi"}, {"key": "C", "text": "Pelaporan non-kas"}, {"key": "D", "text": "Pendanaan"}]'::jsonb,'D','Aktivitas pendanaan (financing activities) adalah aktivitas yang mengakibatkan perubahan dalam jumlah serta komposisi kontribusi modal dan pinjaman entitas. Menerbitkan obligasi berarti perusahaan meminjam uang dari publik, yang akan meningkatkan kas dan juga utang jangka panjang. Oleh karena itu, arus kas masuk dari penerbitan obligasi dilaporkan sebagai aktivitas pendanaan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pembelian kembali saham perusahaan (buyback) akan dilaporkan dalam laporan arus kas sebagai...','[{"key": "A", "text": "Arus kas masuk dari aktivitas pendanaan"}, {"key": "B", "text": "Arus kas keluar dari aktivitas investasi"}, {"key": "C", "text": "Arus kas keluar dari aktivitas pendanaan"}, {"key": "D", "text": "Arus kas masuk dari aktivitas operasi"}]'::jsonb,'C','Pembelian kembali saham (share buyback) adalah transaksi di mana perusahaan menggunakan kasnya untuk membeli kembali sahamnya sendiri dari pasar. Transaksi ini mengurangi jumlah saham yang beredar dan juga mengurangi kas. Karena ini adalah aktivitas yang berkaitan dengan struktur modal (ekuitas) perusahaan, maka diklasifikasikan sebagai arus kas keluar dari aktivitas pendanaan.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari transaksi berikut yang merupakan aktivitas investasi pada laporan arus kas PLN?','[{"key": "A", "text": "Membayar gaji karyawan"}, {"key": "B", "text": "Menjual aset yang sudah tua"}, {"key": "C", "text": "Menerima pinjaman dari bank"}, {"key": "D", "text": "Membayar dividen kepada pemerintah"}]'::jsonb,'B','Aktivitas investasi (investing activities) mencakup pembelian dan penjualan aset jangka panjang serta investasi lain yang tidak termasuk setara kas. Penjualan aset tetap seperti gedung atau mesin pembangkit listrik adalah contoh klasik dari aktivitas investasi yang menghasilkan arus kas masuk. Pembelian aset tetap akan menjadi arus kas keluar dari aktivitas investasi.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio yang digunakan untuk mengukur kemampuan perusahaan membayar kewajiban jangka pendeknya adalah...','[{"key": "A", "text": "Rasio Profitabilitas"}, {"key": "B", "text": "Rasio Solvabilitas"}, {"key": "C", "text": "Rasio Aktivitas"}, {"key": "D", "text": "Rasio Likuiditas"}]'::jsonb,'D','Rasio likuiditas adalah serangkaian metrik yang dirancang untuk mengukur kemampuan perusahaan dalam memenuhi kewajiban jangka pendeknya (utang yang jatuh tempo dalam satu tahun) menggunakan aset lancarnya. Contoh yang paling umum adalah Rasio Lancar (Current Ratio) dan Rasio Cepat (Quick Ratio).','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah Unit Induk PLN memiliki total aset lancar sebesar Rp 200 Miliar dan total utang lancar sebesar Rp 100 Miliar. Berapakah Current Ratio (rasio lancar) unit tersebut?','[{"key": "A", "text": "0.5"}, {"key": "B", "text": "1.0"}, {"key": "C", "text": "2.0"}, {"key": "D", "text": "2.5"}]'::jsonb,'C','Rasio Lancar atau Current Ratio dihitung dengan membagi total aset lancar dengan total utang lancar. Dalam kasus ini, perhitungannya adalah Rp 200 Miliar dibagi dengan Rp 100 Miliar, yang menghasilkan nilai 2.0. Ini berarti unit PLN tersebut memiliki aset lancar sebesar dua kali lipat dari utang lancarnya.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Debt to Equity Ratio (Rasio Utang terhadap Ekuitas) yang tinggi mengindikasikan...','[{"key": "A", "text": "Perusahaan memiliki kemampuan yang baik untuk membayar utang"}, {"key": "B", "text": "Perusahaan lebih banyak dibiayai oleh utang daripada modal sendiri"}, {"key": "C", "text": "Perusahaan memiliki tingkat likuiditas yang tinggi"}, {"key": "D", "text": "Perusahaan sangat efisien dalam menggunakan asetnya"}]'::jsonb,'B','Debt to Equity Ratio (DER) adalah rasio solvabilitas yang membandingkan total utang perusahaan dengan total ekuitas pemegang saham. Rasio yang tinggi (misalnya di atas 1.0) menunjukkan bahwa perusahaan mengandalkan lebih banyak pendanaan dari pinjaman daripada dari modal sendiri, yang dapat meningkatkan risiko keuangan.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk mengukur seberapa efisien manajemen dalam menghasilkan laba dari pendapatan, analis akan menggunakan...','[{"key": "A", "text": "Return on Equity (ROE)"}, {"key": "B", "text": "Current Ratio"}, {"key": "C", "text": "Net Profit Margin (NPM)"}, {"key": "D", "text": "Debt Ratio"}]'::jsonb,'C','Net Profit Margin, atau Margin Laba Bersih, adalah rasio profitabilitas yang dihitung dengan membagi laba bersih dengan total pendapatan atau penjualan. Rasio ini menunjukkan persentase dari setiap rupiah penjualan yang berhasil diubah menjadi laba bersih. Semakin tinggi NPM, semakin efisien perusahaan dalam mengelola biaya-biayanya.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Return on Assets (ROA) dihitung dengan rumus...','[{"key": "A", "text": "Laba Bersih / Total Aset"}, {"key": "B", "text": "Laba Bersih / Total Ekuitas"}, {"key": "C", "text": "Penjualan / Total Aset"}, {"key": "D", "text": "Laba Kotor / Penjualan"}]'::jsonb,'A','Return on Assets (ROA) adalah indikator profitabilitas yang mengukur seberapa efisien sebuah perusahaan dalam menggunakan total asetnya untuk menghasilkan laba. Rasio ini memberikan gambaran tentang kemampuan manajemen dalam menghasilkan keuntungan dari aset yang mereka kelola, terlepas dari bagaimana aset tersebut didanai (utang atau ekuitas).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis vertikal pada laporan laba rugi dilakukan dengan cara...','[{"key": "A", "text": "Membandingkan akun dari tahun ke tahun"}, {"key": "B", "text": "Menyatakan setiap pos sebagai persentase dari total penjualan"}, {"key": "C", "text": "Membandingkan rasio keuangan dengan rata-rata industri"}, {"key": "D", "text": "Menyatakan setiap pos sebagai persentase dari total aset"}]'::jsonb,'B','Analisis vertikal (juga dikenal sebagai analisis common-size) pada laporan laba rugi melibatkan penetapan angka penjualan bersih sebagai dasar 100%. Kemudian, setiap pos lain dalam laporan tersebut, seperti harga pokok penjualan dan biaya operasional, dinyatakan sebagai persentase dari penjualan bersih. Ini membantu dalam memahami struktur biaya dan profitabilitas perusahaan.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah proyek pembangunan pembangkit listrik tenaga surya dianggap layak jika nilai Net Present Value (NPV) nya...','[{"key": "A", "text": "Negatif"}, {"key": "B", "text": "Sama dengan nol"}, {"key": "C", "text": "Positif"}, {"key": "D", "text": "Kurang dari Internal Rate of Return (IRR)"}]'::jsonb,'C','Net Present Value (NPV) adalah selisih antara nilai sekarang (present value) dari arus kas masuk yang diharapkan di masa depan dengan nilai investasi awal. Sebuah proyek dianggap layak secara finansial jika NPV-nya positif, karena ini mengindikasikan bahwa proyek tersebut diharapkan memberikan pengembalian yang lebih tinggi dari tingkat pengembalian yang disyaratkan (discount rate), sehingga akan menambah nilai bagi perusahaan.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode penilaian investasi yang mengukur berapa lama waktu yang dibutuhkan agar arus kas masuk kumulatif sama dengan investasi awal adalah...','[{"key": "A", "text": "Net Present Value (NPV)"}, {"key": "B", "text": "Internal Rate of Return (IRR)"}, {"key": "C", "text": "Payback Period"}, {"key": "D", "text": "Profitability Index (PI)"}]'::jsonb,'C','Payback Period adalah salah satu metode evaluasi investasi yang paling sederhana. Metode ini hanya menghitung berapa lama waktu (dalam tahun atau bulan) yang diperlukan bagi suatu proyek untuk menghasilkan arus kas masuk yang cukup untuk menutupi biaya investasi awalnya. Metode ini sering digunakan sebagai ukuran risiko awal.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika Internal Rate of Return (IRR) dari suatu proyek lebih besar dari biaya modal (cost of capital) perusahaan, maka proyek tersebut sebaiknya...','[{"key": "A", "text": "Diterima"}, {"key": "B", "text": "Ditolak"}, {"key": "C", "text": "Ditunda"}, {"key": "D", "text": "Dikaji ulang dengan metode lain"}]'::jsonb,'A','Internal Rate of Return (IRR) adalah tingkat diskonto yang akan membuat NPV suatu proyek menjadi nol. IRR merepresentasikan tingkat pengembalian (rate of return) yang sebenarnya dari proyek tersebut. Aturan keputusannya adalah: jika IRR lebih besar dari biaya modal perusahaan (cost of capital atau hurdle rate), maka proyek tersebut dianggap menguntungkan dan sebaiknya diterima.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang mempertimbangkan dua proyek ekspansi jaringan. Proyek A memiliki NPV Rp 5 Miliar dan Proyek B memiliki NPV Rp 7 Miliar. Dengan asumsi proyek bersifat mutually exclusive, proyek mana yang harus dipilih?','[{"key": "A", "text": "Proyek A"}, {"key": "B", "text": "Proyek B"}, {"key": "C", "text": "Keduanya"}, {"key": "D", "text": "Tidak ada"}]'::jsonb,'B','Proyek yang bersifat mutually exclusive berarti hanya satu proyek yang dapat dipilih dari beberapa alternatif yang tersedia. Dalam situasi seperti ini, perusahaan harus memilih proyek yang menawarkan nilai tambah terbesar. Dengan menggunakan metode NPV, proyek yang harus dipilih adalah yang memiliki NPV positif tertinggi, yaitu Proyek B dengan NPV Rp 7 Miliar.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kelemahan utama dari metode Payback Period adalah...','[{"key": "A", "text": "Terlalu rumit untuk dihitung"}, {"key": "B", "text": "Selalu memberikan hasil yang sama dengan NPV"}, {"key": "C", "text": "Membutuhkan estimasi tingkat diskonto yang akurat"}, {"key": "D", "text": "Mengabaikan nilai waktu dari uang (time value of money)"}]'::jsonb,'D','Kelemahan utama dari metode Payback Period adalah ia tidak memperhitungkan konsep nilai waktu uang; yaitu bahwa uang yang diterima hari ini lebih berharga daripada uang yang diterima di masa depan. Metode ini memperlakukan semua arus kas sama, tanpa mendiskontokannya. Selain itu, metode ini juga mengabaikan semua arus kas yang terjadi setelah periode payback tercapai.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat diskonto yang membuat NPV suatu proyek sama dengan nol disebut...','[{"key": "A", "text": "Biaya Modal Rata-rata Tertimbang (WACC)"}, {"key": "B", "text": "Tingkat Bunga Efektif"}, {"key": "C", "text": "Internal Rate of Return (IRR)"}, {"key": "D", "text": "Tingkat Inflasi"}]'::jsonb,'C','Sesuai dengan definisinya, Internal Rate of Return (IRR) adalah tingkat pengembalian atau tingkat diskonto unik yang, ketika digunakan untuk menghitung Net Present Value (NPV) dari serangkaian arus kas, akan menghasilkan NPV yang sama dengan nol. Ini adalah metrik penting untuk menilai profitabilitas suatu investasi.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pajak yang dikenakan atas penghasilan yang diterima atau diperoleh Wajib Pajak, baik yang berasal dari Indonesia maupun dari luar Indonesia, adalah...','[{"key": "A", "text": "Pajak Pertambahan Nilai (PPN)"}, {"key": "B", "text": "Pajak Penghasilan (PPh)"}, {"key": "C", "text": "Pajak Bumi dan Bangunan (PBB)"}, {"key": "D", "text": "Bea Materai"}]'::jsonb,'B','Pajak Penghasilan (PPh) adalah jenis pajak yang dikenakan atas penghasilan, yang didefinisikan sebagai setiap tambahan kemampuan ekonomis yang diterima atau diperoleh Wajib Pajak. Penghasilan ini dapat berasal dari mana saja dan dapat digunakan untuk konsumsi atau menambah kekayaan Wajib Pajak, menjadikannya objek dari PPh.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN memungut PPN dari pelanggan atas penjualan tenaga listrik. PPN yang dipungut ini disebut...','[{"key": "A", "text": "Pajak Masukan"}, {"key": "B", "text": "Pajak Keluaran"}, {"key": "C", "text": "PPh Pasal 21"}, {"key": "D", "text": "PPh Pasal 23"}]'::jsonb,'B','Pajak Pertambahan Nilai (PPN) adalah pajak atas konsumsi. Ketika perusahaan Kena Pajak seperti PLN menjual jasa (tenaga listrik), ia wajib memungut PPN dari pembeli (pelanggan). PPN yang dipungut atas penjualan ini disebut sebagai Pajak Keluaran. Nantinya, Pajak Keluaran ini akan diperhitungkan dengan Pajak Masukan (PPN yang dibayar saat membeli barang/jasa).','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaji yang dibayarkan PLN kepada karyawannya akan dipotong pajak...','[{"key": "A", "text": "PPh Pasal 21"}, {"key": "B", "text": "PPh Pasal 22"}, {"key": "C", "text": "PPh Pasal 23"}, {"key": "D", "text": "PPh Pasal 4 ayat (2)"}]'::jsonb,'A','PPh Pasal 21 adalah jenis pajak penghasilan yang dikenakan atas penghasilan yang diterima oleh Wajib Pajak orang pribadi dalam negeri sehubungan dengan pekerjaan, jasa, atau kegiatan. Perusahaan, dalam hal ini PLN, bertindak sebagai pemotong pajak (withholding agent) yang wajib memotong, menyetor, dan melaporkan PPh 21 atas gaji yang dibayarkan kepada karyawannya.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan dari audit internal adalah...','[{"key": "A", "text": "Memberikan opini atas kewajaran laporan keuangan untuk pihak eksternal"}, {"key": "B", "text": "Memastikan kepatuhan terhadap peraturan perpajakan"}, {"key": "C", "text": "Memberikan keyakinan yang independen dan objektif untuk meningkatkan operasi perusahaan"}, {"key": "D", "text": "Menentukan kelayakan kredit perusahaan"}]'::jsonb,'C','Fungsi audit internal adalah sebagai mitra strategis bagi manajemen. Auditor internal secara independen dan objektif mengevaluasi efektivitas proses pengendalian internal, manajemen risiko, dan tata kelola perusahaan. Tujuannya bukan untuk mencari kesalahan, melainkan untuk memberikan rekomendasi perbaikan agar operasi perusahaan menjadi lebih efisien dan efektif.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses penyesuaian catatan akuntansi komersial (laba menurut akuntansi) agar sesuai dengan ketentuan perpajakan disebut...','[{"key": "A", "text": "Rekonsiliasi bank"}, {"key": "B", "text": "Jurnal penyesuaian"}, {"key": "C", "text": "Koreksi fiskal"}, {"key": "D", "text": "Amortisasi"}]'::jsonb,'C','Terdapat perbedaan antara Standar Akuntansi Keuangan (komersial) dan peraturan perpajakan (fiskal) dalam hal pengakuan pendapatan dan biaya. Oleh karena itu, laba yang dihitung secara akuntansi harus disesuaikan agar sesuai dengan ketentuan perpajakan. Proses penyesuaian inilah yang disebut koreksi atau rekonsiliasi fiskal, yang bisa bersifat positif (menambah laba kena pajak) atau negatif (mengurangi laba kena pajak).','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari biaya berikut yang umumnya tidak dapat dikurangkan dari penghasilan bruto (non-deductible expense) dalam perhitungan PPh Badan?','[{"key": "A", "text": "Biaya gaji karyawan"}, {"key": "B", "text": "Biaya rekreasi karyawan"}, {"key": "C", "text": "Biaya penyusutan aset operasional"}, {"key": "D", "text": "Biaya listrik dan air kantor"}]'::jsonb,'B','Dalam peraturan PPh Badan, tidak semua biaya yang dikeluarkan perusahaan dapat menjadi pengurang penghasilan bruto. Biaya yang berkaitan dengan pemberian kenikmatan (benefit in kind) kepada karyawan, seperti biaya rekreasi atau mess, umumnya termasuk dalam kategori non-deductible expense. Artinya, biaya ini tidak boleh dikurangkan dalam menghitung laba kena pajak.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemeriksaan yang dilakukan oleh Kantor Akuntan Publik (KAP) terhadap laporan keuangan perusahaan untuk memberikan opini disebut...','[{"key": "A", "text": "Audit Internal"}, {"key": "B", "text": "Audit Eksternal"}, {"key": "C", "text": "Audit Operasional"}, {"key": "D", "text": "Audit Kepatuhan"}]'::jsonb,'B','Audit eksternal dilakukan oleh auditor independen dari luar perusahaan, yaitu Kantor Akuntan Publik (KAP). Tujuan utamanya adalah untuk memeriksa laporan keuangan perusahaan dan memberikan opini profesional mengenai apakah laporan keuangan tersebut telah disajikan secara wajar, dalam semua hal yang material, sesuai dengan standar akuntansi yang berlaku.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PPh Pasal 23 dikenakan atas jenis penghasilan tertentu, seperti...','[{"key": "A", "text": "Gaji dan upah"}, {"key": "B", "text": "Impor barang"}, {"key": "C", "text": "Dividen, bunga, royalti, dan sewa"}, {"key": "D", "text": "Penjualan tanah dan bangunan"}]'::jsonb,'C','PPh Pasal 23 adalah pajak yang dipotong oleh pihak pembayar penghasilan atas jenis penghasilan tertentu yang dibayarkan kepada Wajib Pajak dalam negeri. Jenis penghasilan ini umumnya berkaitan dengan penggunaan modal (dividen, bunga, royalti), penggunaan aset (sewa), atau imbalan jasa-jasa tertentu selain yang telah dipotong PPh 21.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika laba komersial sebelum pajak lebih besar dari laba fiskal, maka akan terjadi...','[{"key": "A", "text": "Koreksi fiskal positif"}, {"key": "B", "text": "Koreksi fiskal negatif"}, {"key": "C", "text": "Beban pajak tangguhan"}, {"key": "D", "text": "Aset pajak tangguhan"}]'::jsonb,'B','Koreksi fiskal negatif adalah penyesuaian yang menyebabkan penghasilan kena pajak (laba fiskal) menjadi lebih rendah daripada laba menurut akuntansi (komersial). Ini terjadi jika ada pendapatan yang diakui dalam akuntansi tetapi tidak termasuk objek pajak (misalnya, dividen dari anak perusahaan dengan kepemilikan tertentu) atau jika ada biaya yang tidak diakui akuntansi tetapi diakui oleh fiskal.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama dari auditor internal di lingkungan PLN adalah...','[{"key": "A", "text": "Menangkap pelaku kecurangan untuk dilaporkan ke polisi"}, {"key": "B", "text": "Menyiapkan laporan keuangan tahunan"}, {"key": "C", "text": "Mengevaluasi dan meningkatkan efektivitas proses manajemen risiko, pengendalian, dan tata kelola"}, {"key": "D", "text": "Menghitung PPh terutang perusahaan"}]'::jsonb,'C','Ini merangkum peran modern dan strategis dari auditor internal. Di perusahaan besar seperti PLN, auditor internal tidak hanya memeriksa kepatuhan, tetapi juga secara proaktif membantu manajemen mengidentifikasi risiko, mengevaluasi apakah sistem pengendalian internal sudah memadai untuk memitigasi risiko tersebut, dan memastikan proses tata kelola perusahaan berjalan dengan baik.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN memiliki sebuah Pembangkit Listrik Tenaga Uap (PLTU) dengan biaya perolehan Rp 1 Triliun dan diperkirakan memiliki umur ekonomis 20 tahun tanpa nilai sisa. Menggunakan metode penyusutan garis lurus, berapakah beban penyusutan tahunan untuk PLTU tersebut?','[{"key": "A", "text": "Rp 20 Miliar"}, {"key": "B", "text": "Rp 40 Miliar"}, {"key": "C", "text": "Rp 50 Miliar"}, {"key": "D", "text": "Rp 100 Miliar"}]'::jsonb,'C','Metode penyusutan garis lurus mengalokasikan biaya perolehan aset secara merata selama umur ekonomisnya. Rumusnya adalah (Biaya Perolehan - Nilai Sisa) / Umur Ekonomis. Dalam kasus ini, perhitungannya adalah (Rp 1.000.000.000.000 - 0) / 20 tahun = Rp 50.000.000.000 atau Rp 50 Miliar per tahun.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada bulan Desember, PLN telah mengirimkan tagihan listrik kepada pelanggan industri sebesar Rp 5 Miliar, namun pembayaran baru akan diterima pada bulan Januari. Berdasarkan basis akrual, kapan pendapatan tersebut harus diakui?','[{"key": "A", "text": "Diakui di bulan Januari saat kas diterima"}, {"key": "B", "text": "Diakui setengah di Desember dan setengah di Januari"}, {"key": "C", "text": "Diakui sepenuhnya di bulan Desember"}, {"key": "D", "text": "Tidak diakui sampai pelanggan membayar lunas"}]'::jsonb,'C','Prinsip akuntansi basis akrual (accrual basis) menyatakan bahwa pendapatan diakui ketika telah dihasilkan (earned), bukan ketika kas diterima. PLN telah menyelesaikan jasanya (mengirimkan listrik) dan mengeluarkan tagihan di bulan Desember, sehingga hak untuk menagih telah timbul. Oleh karena itu, pendapatan harus diakui sepenuhnya pada bulan Desember.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada tanggal 1 Oktober, PLN membayar premi asuransi untuk armada kendaraannya sebesar Rp 240 juta untuk periode satu tahun. Jurnal penyesuaian yang harus dibuat pada tanggal 31 Desember adalah...','[{"key": "A", "text": "Beban Asuransi (Debit) Rp 60 juta, Asuransi Dibayar di Muka (Kredit) Rp 60 juta"}, {"key": "B", "text": "Asuransi Dibayar di Muka (Debit) Rp 240 juta, Kas (Kredit) Rp 240 juta"}, {"key": "C", "text": "Beban Asuransi (Debit) Rp 240 juta, Kas (Kredit) Rp 240 juta"}, {"key": "D", "text": "Beban Asuransi (Debit) Rp 180 juta, Asuransi Dibayar di Muka (Kredit) Rp 180 juta"}]'::jsonb,'A','Premi asuransi Rp 240 juta adalah untuk 12 bulan. Pada tanggal 31 Desember, 3 bulan (Oktober, November, Desember) telah berlalu, sehingga sebagian dari asuransi dibayar di muka telah menjadi beban. Beban yang diakui adalah (3/12) * Rp 240 juta = Rp 60 juta. Jurnal penyesuaian mencatat penambahan Beban Asuransi di debit dan pengurangan aset Asuransi Dibayar di Muka di kredit.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan dari pembuatan jurnal penutup (closing entries) pada akhir periode akuntansi adalah...','[{"key": "A", "text": "Untuk memastikan total debit sama dengan total kredit"}, {"key": "B", "text": "Untuk memindahkan saldo akun nominal ke akun modal/laba ditahan"}, {"key": "C", "text": "Untuk mencatat transaksi yang belum tercatat selama periode berjalan"}, {"key": "D", "text": "Untuk menghitung penyusutan aset tetap"}]'::jsonb,'B','Akun nominal (atau akun temporer) seperti pendapatan dan beban hanya mengukur aktivitas dalam satu periode akuntansi. Pada akhir periode, saldo akun-akun ini harus dinolkan dan laba atau rugi bersihnya dipindahkan ke akun riil yaitu Laba Ditahan (bagian dari ekuitas). Proses ini dilakukan melalui jurnal penutup.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam laporan posisi keuangan, klaim residual atas aset perusahaan setelah dikurangi semua liabilitas disebut...','[{"key": "A", "text": "Pendapatan"}, {"key": "B", "text": "Aset Lancar"}, {"key": "C", "text": "Liabilitas Jangka Panjang"}, {"key": "D", "text": "Ekuitas"}]'::jsonb,'D','Ekuitas (equity) merepresentasikan hak atau klaim residual pemilik atas aset perusahaan. Nilainya dihitung dengan mengurangkan total liabilitas dari total aset. Ini adalah sisa kekayaan dalam perusahaan yang menjadi hak para pemegang saham setelah semua kewajiban kepada kreditur dipenuhi.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN mengestimasi bahwa 1% dari total piutang usahanya sebesar Rp 10 Triliun tidak akan tertagih. Pencatatan untuk estimasi kerugian piutang ini adalah...','[{"key": "A", "text": "Beban Kerugian Piutang (Debit) Rp 100 M, Piutang Usaha (Kredit) Rp 100 M"}, {"key": "B", "text": "Beban Kerugian Piutang (Debit) Rp 100 M, Cadangan Kerugian Piutang (Kredit) Rp 100 M"}, {"key": "C", "text": "Kas (Debit) Rp 100 M, Piutang Usaha (Kredit) Rp 100 M"}, {"key": "D", "text": "Cadangan Kerugian Piutang (Debit) Rp 100 M, Beban Kerugian Piutang (Kredit) Rp 100 M"}]'::jsonb,'B','Metode penyisihan (allowance method) mengharuskan perusahaan mengestimasi dan mencatat kerugian piutang pada periode yang sama saat penjualan diakui. Estimasi kerugian (1% x Rp 10 T = Rp 100 M) dicatat sebagai Beban Kerugian Piutang di debit dan sebagai pengurang nilai piutang melalui akun kontra-aset Cadangan Kerugian Piutang di kredit.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan contoh biaya variabel dalam operasional sebuah pembangkit listrik?','[{"key": "A", "text": "Gaji supervisor pembangkit"}, {"key": "B", "text": "Pajak Bumi dan Bangunan (PBB) area pembangkit"}, {"key": "C", "text": "Biaya pelumas untuk turbin yang penggunaannya tergantung jam operasional"}, {"key": "D", "text": "Biaya sewa lahan"}]'::jsonb,'C','Biaya variabel adalah biaya yang totalnya berubah secara proporsional dengan perubahan volume aktivitas. Penggunaan pelumas akan meningkat seiring dengan lamanya turbin beroperasi (menghasilkan lebih banyak listrik). Sebaliknya, gaji supervisor dan PBB adalah biaya tetap, sedangkan sewa lahan adalah biaya tetap periodik.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Margin kontribusi (contribution margin) dihitung dengan cara...','[{"key": "A", "text": "Penjualan dikurangi Biaya Variabel"}, {"key": "B", "text": "Penjualan dikurangi Total Biaya"}, {"key": "C", "text": "Penjualan dikurangi Biaya Tetap"}, {"key": "D", "text": "Harga Pokok Penjualan dikurangi Biaya Variabel"}]'::jsonb,'A','Margin kontribusi adalah jumlah pendapatan penjualan yang tersisa setelah dikurangi biaya variabel. Jumlah ini tersedia untuk menutupi biaya tetap dan menghasilkan laba. Margin kontribusi adalah konsep kunci dalam analisis CVP (Cost-Volume-Profit).','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang mempertimbangkan untuk mengganti turbin lama dengan yang baru. Biaya perolehan turbin lama yang sudah terjadi di masa lalu merupakan contoh dari...','[{"key": "A", "text": "Opportunity Cost"}, {"key": "B", "text": "Incremental Cost"}, {"key": "C", "text": "Variable Cost"}, {"key": "D", "text": "Sunk Cost"}]'::jsonb,'D','Sunk cost (biaya terbenam) adalah biaya yang telah terjadi di masa lalu dan tidak dapat diubah atau dihindari oleh keputusan apa pun yang dibuat di masa sekarang atau masa depan. Dalam pengambilan keputusan, sunk cost tidak relevan dan harus diabaikan. Biaya perolehan turbin lama adalah contoh klasik dari sunk cost.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem perhitungan biaya yang paling sesuai untuk perusahaan yang menghasilkan produk homogen dan massal seperti listrik adalah...','[{"key": "A", "text": "Job Order Costing"}, {"key": "B", "text": "Process Costing"}, {"key": "C", "text": "Activity Based Costing"}, {"key": "D", "text": "Target Costing"}]'::jsonb,'B','Process costing adalah sistem akuntansi biaya yang digunakan ketika perusahaan memproduksi produk yang identik (homogen) secara terus-menerus dan massal. Biaya diakumulasikan per departemen atau proses untuk suatu periode waktu. Ini sangat cocok untuk industri seperti pembangkitan listrik, penyulingan minyak, atau produksi bahan kimia.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis CVP (Cost-Volume-Profit) digunakan oleh manajemen untuk...','[{"key": "A", "text": "Menganalisis hubungan antar biaya, volume penjualan dan laba"}, {"key": "B", "text": "Menentukan biaya produk per unit secara akurat"}, {"key": "C", "text": "Mengevaluasi kinerja departemen pendukung"}, {"key": "D", "text": "Mengalokasikan biaya overhead pabrik"}]'::jsonb,'A','Analisis CVP adalah alat bantu manajerial yang digunakan untuk mempelajari hubungan antara biaya, volume penjualan, dan laba. Analisis ini membantu manajer dalam membuat keputusan tentang penetapan harga, bauran produk, dan untuk memprediksi laba pada berbagai tingkat aktivitas.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya yang memiliki komponen tetap dan variabel sekaligus, seperti tagihan telepon yang ada biaya abonemen (tetap) dan biaya per pulsa (variabel), disebut...','[{"key": "A", "text": "Biaya Campuran (Mixed Cost)"}, {"key": "B", "text": "Biaya Bertahap (Step Cost)"}, {"key": "C", "text": "Biaya Peluang (Opportunity Cost)"}, {"key": "D", "text": "Biaya Diferensial"}]'::jsonb,'A','Biaya campuran, atau biaya semivariabel, adalah biaya yang mengandung unsur biaya tetap dan biaya variabel. Ada komponen biaya dasar yang harus dibayar terlepas dari tingkat aktivitas (elemen tetap), dan ada komponen biaya yang berfluktuasi sesuai dengan penggunaan atau aktivitas (elemen variabel).','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika PLN mengakuisisi sebuah perusahaan energi lain dengan harga beli yang lebih tinggi dari nilai wajar aset bersih yang dapat diidentifikasi, selisih tersebut dicatat sebagai...','[{"key": "A", "text": "Laba atas Pembelian"}, {"key": "B", "text": "Goodwill"}, {"key": "C", "text": "Amortisasi"}, {"key": "D", "text": "Aset Tak Berwujud Lainnya"}]'::jsonb,'B','Dalam akuisisi bisnis, goodwill muncul ketika harga beli yang dibayarkan oleh perusahaan pengakuisisi melebihi nilai wajar dari aset bersih (total aset dikurangi total liabilitas) yang dapat diidentifikasi dari perusahaan yang diakuisisi. Goodwill merepresentasikan aset tak berwujud seperti reputasi merek, hubungan pelanggan, atau sinergi.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika PLN memiliki 30% saham di perusahaan pemasok dan memiliki pengaruh signifikan (namun bukan pengendalian), investasi tersebut harus dicatat menggunakan metode...','[{"key": "A", "text": "Metode Biaya (Cost Method)"}, {"key": "B", "text": "Metode Nilai Wajar"}, {"key": "C", "text": "Konsolidasi Penuh"}, {"key": "D", "text": "Metode Ekuitas (Equity Method)"}]'::jsonb,'D','Metode ekuitas digunakan untuk mencatat investasi pada perusahaan asosiasi, di mana investor memiliki pengaruh signifikan (biasanya kepemilikan antara 20% hingga 50%). Dengan metode ini, akun investasi awalnya dicatat sebesar biaya perolehan, kemudian disesuaikan setiap periode untuk mengakui bagian investor atas laba atau rugi perusahaan asosiasi.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan contoh aktivitas investasi dan pendanaan non-kas?','[{"key": "A", "text": "Membayar dividen tunai kepada pemegang saham"}, {"key": "B", "text": "Membeli gedung kantor secara tunai"}, {"key": "C", "text": "Mengakuisisi mesin pembangkit dengan menerbitkan saham biasa"}, {"key": "D", "text": "Menjual investasi jangka pendek untuk mendapatkan kas"}]'::jsonb,'C','Aktivitas investasi dan pendanaan non-kas adalah transaksi signifikan yang tidak melibatkan arus kas masuk atau keluar secara langsung. Contohnya adalah pertukaran aset non-kas dengan aset non-kas lain, atau perolehan aset dengan menerbitkan utang atau saham. Transaksi ini tidak dilaporkan dalam badan laporan arus kas tetapi harus diungkapkan dalam catatan atas laporan keuangan.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam menyusun laporan arus kas metode tidak langsung, penambahan pada akun piutang usaha akan...','[{"key": "A", "text": "Menambahkan laba bersih"}, {"key": "B", "text": "Mengurangkan laba bersih"}, {"key": "C", "text": "Tidak mempengaruhi arus kas dari aktivitas operasi"}, {"key": "D", "text": "Dilaporkan sebagai aktivitas investasi"}]'::jsonb,'B','Dalam metode tidak langsung, arus kas dari operasi dimulai dari laba bersih dan disesuaikan untuk item non-kas dan perubahan modal kerja. Kenaikan piutang usaha berarti perusahaan memiliki lebih banyak penjualan secara kredit daripada yang berhasil ditagih tunai. Oleh karena itu, meskipun laba bersih tinggi, kas yang sebenarnya diterima lebih rendah, sehingga kenaikan piutang harus dikurangkan dari laba bersih.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama eliminasi transaksi antarperusahaan dalam proses konsolidasi adalah...','[{"key": "A", "text": "Untuk menyajikan laporan keuangan seolah-olah grup adalah satu entitas tunggal"}, {"key": "B", "text": "Untuk meningkatkan laba bersih konsolidasi"}, {"key": "C", "text": "Untuk mengurangi total aset grup"}, {"key": "D", "text": "Untuk mematuhi peraturan perpajakan"}]'::jsonb,'A','Laporan konsolidasi bertujuan untuk menunjukkan posisi keuangan dan hasil operasi dari entitas induk dan anak perusahaannya seolah-olah mereka adalah satu perusahaan. Oleh karena itu, semua transaksi yang terjadi di antara mereka (seperti penjualan antarperusahaan atau pinjaman antarperusahaan) harus dieliminasi agar tidak terjadi perhitungan ganda atas pendapatan, beban, aset, dan liabilitas.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Laporan yang menyajikan rincian perubahan modal disetor dan laba ditahan selama satu periode adalah...','[{"key": "A", "text": "Laporan Laba Rugi Komprehensif"}, {"key": "B", "text": "Laporan Posisi Keuangan"}, {"key": "C", "text": "Laporan Arus Kas"}, {"key": "D", "text": "Laporan Perubahan Ekuitas"}]'::jsonb,'D','Laporan Perubahan Ekuitas (atau Laporan Perubahan Modal) merangkum perubahan yang terjadi pada komponen ekuitas perusahaan selama satu periode akuntansi. Laporan ini menyajikan saldo awal, penambahan (seperti laba bersih dan penerbitan saham), pengurangan (seperti rugi bersih dan dividen), dan saldo akhir dari setiap akun ekuitas.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio yang mengukur kemampuan perusahaan membayar kewajiban lancar tanpa mengandalkan persediaan adalah...','[{"key": "A", "text": "Current Ratio"}, {"key": "B", "text": "Debt to Equity Ratio"}, {"key": "C", "text": "Quick Ratio"}, {"key": "D", "text": "Inventory Turnover"}]'::jsonb,'C','Quick Ratio adalah ukuran likuiditas yang lebih konservatif dibandingkan Current Ratio. Rasionya dihitung dengan (Aset Lancar - Persediaan) / Utang Lancar. Persediaan tidak diikutsertakan karena dianggap sebagai aset lancar yang paling tidak likuid, atau paling sulit untuk diubah menjadi kas dalam waktu cepat.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio Perputaran Total Aset (Total Asset Turnover) yang tinggi menunjukkan...','[{"key": "A", "text": "Perusahaan memiliki banyak utang"}, {"key": "B", "text": "Perusahaan sangat likuid"}, {"key": "C", "text": "Manajemen efisien dalam menggunakan aset untuk menghasilkan penjualan"}, {"key": "D", "text": "Perusahaan memiliki margin keuntungan yang tinggi"}]'::jsonb,'C','Rasio Perputaran Total Aset (Penjualan / Rata-rata Total Aset) adalah rasio aktivitas yang mengukur seberapa efisien perusahaan menggunakan seluruh asetnya untuk menghasilkan pendapatan penjualan. Rasio yang lebih tinggi umumnya menunjukkan pemanfaatan aset yang lebih baik.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis DuPont memecah Return on Equity (ROE) menjadi tiga komponen, yaitu...','[{"key": "A", "text": "Likuiditas, Solvabilitas, dan Aktivitas"}, {"key": "B", "text": "Profitabilitas, Efisiensi Aset, dan Leverage Keuangan"}, {"key": "C", "text": "Arus Kas Operasi, Investasi, dan Pendanaan"}, {"key": "D", "text": "Margin Laba Kotor, Margin Laba Operasi, dan Margin Laba Bersih"}]'::jsonb,'B','Analisis DuPont adalah kerangka kerja yang menguraikan Return on Equity (ROE) menjadi tiga komponen: Net Profit Margin (ukuran profitabilitas), Total Asset Turnover (ukuran efisiensi penggunaan aset), dan Equity Multiplier (ukuran leverage keuangan). Rumusnya: ROE = (Net Profit Margin) x (Total Asset Turnover) x (Equity Multiplier).','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN memiliki utang obligasi yang besar untuk mendanai proyek infrastruktur. Rasio yang paling tepat untuk mengukur kemampuan perusahaan menutupi beban bunga dari laba operasinya adalah...','[{"key": "A", "text": "Debt Ratio"}, {"key": "B", "text": "Return on Assets (ROA)"}, {"key": "C", "text": "Times Interest Earned (TIE) Ratio"}, {"key": "D", "text": "Price to Earnings (P/E) Ratio"}]'::jsonb,'C','TIE Ratio, atau rasio kelipatan bunga yang dihasilkan, adalah rasio solvabilitas yang mengukur kemampuan perusahaan untuk memenuhi kewajiban pembayaran bunga periodiknya. Dihitung dengan membagi Laba Sebelum Bunga dan Pajak (EBIT) dengan Beban Bunga. Rasio yang tinggi menunjukkan kemampuan membayar bunga yang baik.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang membandingkan data keuangan perusahaan selama beberapa periode untuk melihat tren pertumbuhan atau penurunan disebut...','[{"key": "A", "text": "Analisis Vertikal"}, {"key": "B", "text": "Analisis Rasio"}, {"key": "C", "text": "Analisis Horizontal"}, {"key": "D", "text": "Analisis Industri"}]'::jsonb,'C','Analisis horizontal, juga dikenal sebagai analisis tren, melibatkan perbandingan angka-angka dalam laporan keuangan dari satu periode ke periode lainnya (misalnya, membandingkan laporan keuangan 2024 dengan 2023). Tujuannya adalah untuk mengidentifikasi arah dan kecepatan perubahan dalam kinerja keuangan perusahaan.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara Gross Profit Margin dan Net Profit Margin adalah...','[{"key": "A", "text": "Gross Profit Margin tidak memperhitungkan harga pokok penjualan"}, {"key": "B", "text": "Net Profit Margin memperhitungkan semua biaya, termasuk pajak dan bunga"}, {"key": "C", "text": "Gross Profit Margin hanya digunakan oleh perusahaan manufaktur"}, {"key": "D", "text": "Net Profit Margin selalu lebih tinggi dari Gross Profit Margin"}]'::jsonb,'B','Gross Profit Margin (Margin Laba Kotor) hanya memperhitungkan biaya langsung produksi (Harga Pokok Penjualan). Sedangkan Net Profit Margin (Margin Laba Bersih) memperhitungkan semua biaya yang terjadi dalam perusahaan, termasuk biaya operasional (penjualan, umum, & administrasi), beban bunga, dan pajak penghasilan.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aturan pengambilan keputusan untuk metode Profitability Index (PI) adalah...','[{"key": "A", "text": "Terima proyek jika PI lebih besar dari 1"}, {"key": "B", "text": "Terima proyek jika PI lebih kecil dari 1"}, {"key": "C", "text": "Terima proyek jika PI sama dengan 0"}, {"key": "D", "text": "Terima proyek jika PI sama dengan IRR"}]'::jsonb,'A','Profitability Index (PI) dihitung dengan membagi nilai sekarang dari arus kas masuk masa depan dengan investasi awal. PI yang lebih besar dari 1 menunjukkan bahwa nilai sekarang dari arus kas masuk lebih besar dari investasi awal, yang berarti proyek tersebut memiliki NPV positif dan layak untuk diterima.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Weighted Average Cost of Capital (WACC) digunakan dalam analisis NPV sebagai...','[{"key": "A", "text": "Arus kas masuk tahunan"}, {"key": "B", "text": "Investasi awal proyek"}, {"key": "C", "text": "Tingkat diskonto (discount rate)"}, {"key": "D", "text": "Umur ekonomis proyek"}]'::jsonb,'C','WACC merepresentasikan biaya modal rata-rata dari semua sumber pendanaan perusahaan (utang dan ekuitas). Dalam analisis penganggaran modal seperti NPV, WACC sering digunakan sebagai tingkat diskonto untuk menghitung nilai sekarang dari arus kas masa depan. WACC adalah tingkat pengembalian minimum yang harus dihasilkan proyek agar dapat menambah nilai perusahaan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam kondisi tertentu, metode NPV dan IRR dapat memberikan rekomendasi yang bertentangan untuk proyek yang bersifat mutually exclusive. Dalam situasi ini, metode yang lebih superior dan harus diikuti adalah...','[{"key": "A", "text": "IRR karena menunjukkan persentase"}, {"key": "B", "text": "NPV karena mengukur penambahan nilai absolut"}, {"key": "C", "text": "Payback Period karena lebih sederhana"}, {"key": "D", "text": "Keduanya harus diabaikan"}]'::jsonb,'B','Ketika terjadi konflik antara NPV dan IRR (biasanya pada proyek mutually exclusive dengan skala atau pola arus kas yang berbeda), NPV dianggap sebagai metode yang superior. Alasannya adalah karena NPV secara langsung mengukur berapa banyak nilai (dalam mata uang absolut) yang akan ditambahkan proyek tersebut ke perusahaan, yang sejalan dengan tujuan utama memaksimumkan kekayaan pemegang saham.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang digunakan untuk menguji seberapa besar perubahan NPV suatu proyek jika satu variabel kunci (misalnya, volume penjualan) berubah adalah...','[{"key": "A", "text": "Analisis Skenario"}, {"key": "B", "text": "Analisis Sensitivitas"}, {"key": "C", "text": "Analisis Monte Carlo"}, {"key": "D", "text": "Analisis Titik Impas"}]'::jsonb,'B','Analisis sensitivitas adalah teknik analisis risiko dalam penganggaran modal di mana satu variabel input (seperti harga jual atau biaya variabel) diubah sementara variabel lainnya dianggap konstan, untuk melihat dampaknya terhadap output (seperti NPV atau IRR). Ini membantu manajer memahami variabel mana yang paling kritis terhadap keberhasilan proyek.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Konsep dasar Time Value of Money menyatakan bahwa...','[{"key": "A", "text": "Uang yang diterima di masa depan lebih berharga daripada hari ini"}, {"key": "B", "text": "Nilai uang tidak berubah seiring waktu"}, {"key": "C", "text": "Uang yang diterima hari ini lebih berharga daripada jumlah yang sama di masa depan"}, {"key": "D", "text": "Inflasi tidak mempengaruhi nilai uang"}]'::jsonb,'C','Ini adalah prinsip fundamental dalam keuangan. Sejumlah uang yang dimiliki hari ini memiliki nilai lebih tinggi daripada jumlah uang yang sama di masa depan karena potensi kapasitas penghasilannya (misalnya, dapat diinvestasikan untuk mendapatkan bunga). Oleh karena itu, arus kas masa depan harus didiskontokan untuk menentukan nilainya saat ini.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode Payback Period yang memperhitungkan nilai waktu uang disebut...','[{"key": "A", "text": "Internal Rate of Return (IRR)"}, {"key": "B", "text": "Net Present Value (NPV)"}, {"key": "C", "text": "Discounted Payback Period"}, {"key": "D", "text": "Modified Internal Rate of Return (MIRR)"}]'::jsonb,'C','Discounted Payback Period adalah variasi dari metode Payback Period yang mengatasi kelemahan utamanya. Metode ini menghitung berapa lama waktu yang dibutuhkan untuk mengembalikan investasi awal berdasarkan arus kas yang telah didiskontokan (dihitung nilai sekarangnya), sehingga memperhitungkan nilai waktu dari uang.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PPh Pasal 22 adalah pajak yang dipungut antara lain atas kegiatan...','[{"key": "A", "text": "Pembayaran gaji kepada karyawan tetap"}, {"key": "B", "text": "Impor barang atau pembelian barang oleh bendaharawan pemerintah"}, {"key": "C", "text": "Pembayaran sewa gedung"}, {"key": "D", "text": "Pembayaran dividen kepada pemegang saham"}]'::jsonb,'B','PPh Pasal 22 adalah bentuk pemotongan atau pemungutan PPh yang dikenakan pada badan usaha tertentu, baik pemerintah maupun swasta, yang melakukan kegiatan perdagangan barang, seperti kegiatan impor, ekspor, atau pembelian barang oleh bendaharawan pemerintah/BUMN.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Upaya Wajib Pajak untuk mengurangi beban pajak dengan cara yang tidak melanggar hukum (memanfaatkan celah peraturan) disebut...','[{"key": "A", "text": "Penggelapan Pajak (Tax Evasion)"}, {"key": "B", "text": "Perencanaan Pajak (Tax Planning)"}, {"key": "C", "text": "Pemeriksaan Pajak"}, {"key": "D", "text": "Restitusi Pajak"}]'::jsonb,'B','Perencanaan Pajak (sering juga disebut tax avoidance yang sah) adalah analisis sistematis terhadap berbagai alternatif perpajakan dengan tujuan untuk meminimalkan beban pajak dalam batas-batas ketentuan yang berlaku. Ini berbeda dengan penggelapan pajak (tax evasion) yang merupakan tindakan ilegal untuk tidak membayar pajak.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aset yang timbul karena adanya perbedaan temporer yang dapat dikurangkan, di mana perusahaan akan membayar pajak lebih sedikit di masa depan, disebut...','[{"key": "A", "text": "Aset Pajak Kini"}, {"key": "B", "text": "Aset Pajak Tangguhan"}, {"key": "C", "text": "Liabilitas Pajak Kini"}, {"key": "D", "text": "Liabilitas Pajak Tangguhan"}]'::jsonb,'B','Aset Pajak Tangguhan (Deferred Tax Asset) timbul ketika ada perbedaan temporer yang dapat dikurangkan atau rugi fiskal yang belum dikompensasi. Ini pada dasarnya adalah pengakuan bahwa perusahaan telah membayar pajak lebih banyak daripada beban pajak yang seharusnya diakui untuk periode berjalan, dan kelebihan pembayaran ini akan dapat dipulihkan di masa depan.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Opini audit yang menyatakan bahwa laporan keuangan disajikan secara wajar dalam semua hal yang material, tanpa ada pengecualian, adalah...','[{"key": "A", "text": "Opini Wajar Dengan Pengecualian (Qualified Opinion)"}, {"key": "B", "text": "Opini Tidak Wajar (Adverse Opinion)"}, {"key": "C", "text": "Opini Wajar Tanpa Pengecualian (Unqualified Opinion)"}, {"key": "D", "text": "Tidak Memberikan Pendapat (Disclaimer of Opinion)"}]'::jsonb,'C','Ini adalah jenis opini audit terbaik yang bisa didapatkan perusahaan. Opini ini, juga dikenal sebagai "opini bersih" (clean opinion), menunjukkan bahwa auditor telah menyimpulkan bahwa laporan keuangan perusahaan bebas dari salah saji material dan disajikan secara wajar sesuai dengan prinsip akuntansi yang berlaku umum.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Representasi yang dibuat oleh manajemen, baik secara eksplisit maupun implisit, yang terkandung dalam laporan keuangan dan menjadi subjek pemeriksaan auditor disebut...','[{"key": "A", "text": "Asersi Manajemen"}, {"key": "B", "text": "Surat Representasi"}, {"key": "C", "text": "Opini Audit"}, {"key": "D", "text": "Kertas Kerja Audit"}]'::jsonb,'A','Asersi adalah klaim yang dibuat oleh manajemen mengenai pengakuan, pengukuran, penyajian, dan pengungkapan berbagai elemen dalam laporan keuangan. Auditor menggunakan asersi ini sebagai titik awal untuk mengumpulkan bukti audit. Contoh asersi adalah kelengkapan (semua transaksi telah dicatat) dan eksistensi (aset benar-benar ada).','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perencanaan Pajak (Tax Planning) yang baik harus memenuhi syarat berikut, KECUALI...','[{"key": "A", "text": "Tidak melanggar ketentuan perpajakan yang berlaku"}, {"key": "B", "text": "Masuk akal secara bisnis"}, {"key": "C", "text": "Mengandalkan bukti-bukti yang tidak memadai"}, {"key": "D", "text": "Didukung oleh dokumen yang valid"}]'::jsonb,'C','Perencanaan pajak yang sah dan dapat dipertahankan harus didukung oleh bukti dan dokumentasi yang kuat dan memadai. Mengandalkan bukti yang tidak cukup akan membuat skema perencanaan pajak tersebut rentan dibatalkan oleh otoritas pajak saat pemeriksaan, yang dapat berujung pada sanksi dan denda.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komite di bawah Dewan Komisaris yang bertugas membantu dalam pengawasan atas pelaporan keuangan dan proses audit adalah...','[{"key": "A", "text": "Komite Nominasi dan Remunerasi"}, {"key": "B", "text": "Komite Audit"}, {"key": "C", "text": "Komite Manajemen Risiko"}, {"key": "D", "text": "Komite Strategi"}]'::jsonb,'B','Komite Audit adalah sub-komite dari Dewan Komisaris yang memiliki peran penting dalam tata kelola perusahaan. Tanggung jawab utamanya meliputi pengawasan atas integritas laporan keuangan, kepatuhan terhadap hukum dan peraturan, kualifikasi dan independensi auditor eksternal, serta kinerja fungsi audit internal.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tarif PPh Badan (Wajib Pajak Dalam Negeri berbentuk Perseroan Terbuka) yang berlaku umum saat ini di Indonesia adalah...','[{"key": "A", "text": "10%"}, {"key": "B", "text": "15%"}, {"key": "C", "text": "22%"}, {"key": "D", "text": "25%"}]'::jsonb,'C','Sesuai dengan Undang-Undang Harmonisasi Peraturan Perpajakan (UU HPP), tarif Pajak Penghasilan (PPh) Badan yang berlaku umum untuk tahun pajak 2022 dan seterusnya adalah sebesar 22%.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PPh yang bersifat final berarti...','[{"key": "A", "text": "Pajak tersebut dapat dikreditkan di akhir tahun"}, {"key": "B", "text": "Pemotongan atau pembayarannya merupakan pelunasan akhir atas penghasilan tersebut"}, {"key": "C", "text": "Hanya berlaku untuk Wajib Pajak Orang Pribadi"}, {"key": "D", "text": "Tarifnya selalu lebih rendah dari tarif umum"}]'::jsonb,'B','Penghasilan yang dikenai PPh Final berarti urusan perpajakannya telah selesai pada saat pemotongan atau pembayaran. Pajak yang telah dipotong tidak dapat dikreditkan (tidak dapat menjadi pengurang) dalam penghitungan PPh terutang di SPT Tahunan, dan penghasilannya tidak perlu digabungkan lagi dengan penghasilan lain yang dikenai tarif umum.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika auditor tidak dapat memperoleh bukti yang cukup dan tepat sebagai dasar untuk memberikan opini, dan ia menyimpulkan bahwa dampak yang tidak terdeteksi bisa jadi material dan pervasif, maka auditor akan memberikan...','[{"key": "A", "text": "Opini Wajar Tanpa Pengecualian"}, {"key": "B", "text": "Opini Wajar Dengan Pengecualian"}, {"key": "C", "text": "Opini Tidak Wajar"}, {"key": "D", "text": "Tidak Memberikan Pendapat (Disclaimer of Opinion)"}]'::jsonb,'D','Auditor akan mengeluarkan disclaimer of opinion ketika ruang lingkup auditnya sangat dibatasi sehingga ia tidak dapat memperoleh bukti yang cukup untuk membentuk suatu opini. Ketidakmampuan untuk mendapatkan bukti ini begitu signifikan dan pervasif sehingga auditor tidak dapat menyimpulkan apa pun mengenai kewajaran laporan keuangan secara keseluruhan.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada tanggal 5 Januari, Unit Pembangkit Listrik Tenaga Uap (PLTU) PLN membeli persediaan batu bara senilai Rp 800.000.000 secara kredit dari pemasok. Jurnal untuk mencatat transaksi pembelian persediaan ini adalah...','[{"key": "A", "text": "Persediaan (Debit) Rp 800jt, Kas (Kredit) Rp 800jt"}, {"key": "B", "text": "Beban Batu Bara (Debit) Rp 800jt, Utang Usaha (Kredit) Rp 800jt"}, {"key": "C", "text": "Persediaan (Debit) Rp 800jt, Utang Usaha (Kredit) Rp 800jt"}, {"key": "D", "text": "Utang Usaha (Debit) Rp 800jt, Persediaan (Kredit) Rp 800jt"}]'::jsonb,'C','Pembelian batu bara dicatat sebagai penambahan aset dalam bentuk Persediaan (Debit). Karena pembelian dilakukan secara kredit, kewajiban perusahaan bertambah, yang dicatat sebagai Utang Usaha (Kredit). Batu bara belum menjadi ''Beban'' sampai nanti digunakan atau dikonsumsi untuk menghasilkan listrik.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada tanggal 31 Desember, departemen SDM PLN menghitung total gaji operator pembangkit yang belum dibayar untuk minggu terakhir Desember adalah Rp 150.000.000. Gaji ini baru akan dibayarkan pada 3 Januari. Jurnal penyesuaian yang harus dibuat pada 31 Desember adalah...','[{"key": "A", "text": "Beban Gaji (Debit) Rp 150jt, Kas (Kredit) Rp 150jt"}, {"key": "B", "text": "Beban Gaji (Debit) Rp 150jt, Utang Gaji (Kredit) Rp 150jt"}, {"key": "C", "text": "Utang Gaji (Debit) Rp 150jt, Beban Gaji (Kredit) Rp 150jt"}, {"key": "D", "text": "Tidak perlu jurnal sampai pembayaran di 3 Januari"}]'::jsonb,'B','Berdasarkan prinsip akrual dan matching concept, perusahaan harus mengakui beban pada periode terjadinya, meskipun kas belum keluar. Gaji tersebut adalah beban untuk pekerjaan yang dilakukan di bulan Desember. Oleh karena itu, Beban Gaji diakui (Debit) dan dicatat kewajiban yang timbul sebagai Utang Gaji (Kredit).','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Laporan Posisi Keuangan PLN Unit Wilayah A menunjukkan data berikut: Kas Rp 50 Miliar, Setara Kas (Deposito < 3 bulan) Rp 150 Miliar, Piutang Usaha Rp 300 Miliar, dan Total Utang Lancar Rp 400 Miliar. Berapakah Rasio Kas (Cash Ratio) unit tersebut?','[{"key": "A", "text": "0,50"}, {"key": "B", "text": "1,25"}, {"key": "C", "text": "0,75"}, {"key": "D", "text": "2,00"}]'::jsonb,'A','Rasio Kas adalah rasio likuiditas yang paling konservatif, mengukur kemampuan perusahaan membayar utang lancar hanya dengan kas dan setara kas. Rumus: (Kas + Setara Kas) / Total Utang Lancar. Perhitungan: (Rp 50 Miliar + Rp 150 Miliar) / Rp 400 Miliar = Rp 200 Miliar / Rp 400 Miliar = 0,50.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah Unit Induk PLN memiliki Total Aset Lancar sebesar Rp 1.200 Miliar dan Total Utang Lancar sebesar Rp 900 Miliar. Berapakah jumlah Modal Kerja (Working Capital) bersih unit tersebut?','[{"key": "A", "text": "Rp 300 Miliar"}, {"key": "B", "text": "Rp 900 Miliar"}, {"key": "C", "text": "Rp 1.200 Miliar"}, {"key": "D", "text": "Rp 2.100 Miliar"}]'::jsonb,'A','Modal Kerja (Net Working Capital) adalah selisih antara Aset Lancar dan Utang Lancar. Ini menunjukkan kesehatan keuangan jangka pendek perusahaan. Rumus: Total Aset Lancar - Total Utang Lancar. Perhitungan: Rp 1.200 Miliar - Rp 900 Miliar = Rp 300 Miliar.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip akuntansi yang mengharuskan PLN untuk mencatat biaya (beban) pembelian batu bara pada periode yang sama saat pendapatan dari penjualan listrik (yang dihasilkan dari batu bara tersebut) diakui adalah...','[{"key": "A", "text": "Prinsip Konsistensi (Consistency Principle)"}, {"key": "B", "text": "Prinsip Pengakuan Pendapatan (Revenue Recognition Principle)"}, {"key": "C", "text": "Prinsip Biaya Historis (Historical Cost Principle)"}, {"key": "D", "text": "Prinsip Penandingan (Matching Concept)"}]'::jsonb,'D','Matching Concept (atau Prinsip Penandingan) adalah prinsip dasar akuntansi akrual yang menyatakan bahwa beban harus diakui (ditandingkan) pada periode yang sama dengan pendapatan yang dihasilkannya. Biaya batu bara (beban pokok) harus ditandingkan dengan pendapatan penjualan listrik yang dihasilkan dari batu bara tersebut.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam menyusun laporan keuangan, PLN secara konsisten menggunakan metode penyusutan garis lurus untuk aset jaringan transmisinya dari tahun ke tahun. Hal ini sesuai dengan prinsip akuntansi...','[{"key": "A", "text": "Prinsip Materialitas"}, {"key": "B", "text": "Prinsip Konsistensi"}, {"key": "C", "text": "Prinsip Entitas Ekonomi"}, {"key": "D", "text": "Prinsip Kehati-hatian (Conservatism)"}]'::jsonb,'B','Prinsip Konsistensi mengharuskan perusahaan untuk menerapkan metode akuntansi yang sama untuk item-item yang serupa dari satu periode ke periode berikutnya. Ini bertujuan agar laporan keuangan antar periode dapat diperbandingkan (komparabel) secara adil.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Laporan Laba Rugi PLN menunjukkan Pendapatan Usaha sebesar Rp 300 Triliun pada tahun 2023 dan Rp 250 Triliun pada tahun 2022. Berapakah persentase kenaikan pendapatan usaha dari tahun 2022 ke 2023 (Analisis Horizontal)?','[{"key": "A", "text": "16,67%"}, {"key": "B", "text": "20,00%"}, {"key": "C", "text": "25,00%"}, {"key": "D", "text": "83,33%"}]'::jsonb,'B','Analisis horizontal mengukur perubahan persentase suatu akun dari satu periode ke periode berikutnya. Rumus: ((Nilai Tahun Ini - Nilai Tahun Lalu) / Nilai Tahun Lalu) * 100%. Perhitungan: ((Rp 300 T - Rp 250 T) / Rp 250 T) * 100% = (Rp 50 T / Rp 250 T) * 100% = 0,20 * 100% = 20,00%.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Laporan keuangan utama yang menyajikan rincian perubahan Laba Ditahan (Retained Earnings) PLN, termasuk dampak dari laba bersih tahun berjalan dan pembayaran dividen kepada pemerintah, adalah...','[{"key": "A", "text": "Neraca (Laporan Posisi Keuangan)"}, {"key": "B", "text": "Laporan Laba Rugi Komprehensif"}, {"key": "C", "text": "Laporan Perubahan Ekuitas"}, {"key": "D", "text": "Laporan Arus Kas"}]'::jsonb,'C','Laporan Perubahan Ekuitas merinci semua perubahan yang terjadi pada komponen ekuitas pemilik selama satu periode. Laporan ini dimulai dengan saldo awal Laba Ditahan, ditambah Laba Bersih tahun berjalan, dan dikurangi oleh Dividen yang dibayarkan, sehingga menghasilkan saldo akhir Laba Ditahan.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Setelah mencatat jurnal penyesuaian untuk utang gaji (Beban Gaji di Debit, Utang Gaji di Kredit) pada 31 Desember, akuntan PLN membuat "Jurnal Pembalik" (Reversing Entry) pada 1 Januari tahun berikutnya. Apa tujuan utama dari Jurnal Pembalik?','[{"key": "A", "text": "Untuk membatalkan transaksi yang salah di tahun sebelumnya"}, {"key": "B", "text": "Untuk menyederhanakan pencatatan pembayaran gaji yang sebenarnya di bulan Januari"}, {"key": "C", "text": "Untuk mengakui penerimaan kas di awal periode"}, {"key": "D", "text": "Untuk menghitung penyusutan aset tetap"}]'::jsonb,'B','Jurnal Pembalik (Utang Gaji di Debit, Beban Gaji di Kredit) adalah jurnal opsional yang dibuat pada awal periode baru untuk membalik jurnal penyesuaian akrual. Tujuannya adalah untuk menyederhanakan proses pencatatan. Saat gaji dibayar penuh di bulan Januari, akuntan dapat langsung mencatatnya (Beban Gaji di Debit, Kas di Kredit) tanpa perlu memecah mana yang untuk utang tahun lalu dan mana yang untuk beban tahun ini.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Standar Akuntansi Keuangan (PSAK) utama yang menjadi acuan PLN dalam mencatat perolehan, penyusutan, dan revaluasi aset fisik jangka panjang seperti Pembangkit Listrik (PLTU, PLTA) dan Jaringan Transmisi adalah...','[{"key": "A", "text": "PSAK 1: Penyajian Laporan Keuangan"}, {"key": "B", "text": "PSAK 72: Pendapatan dari Kontrak dengan Pelanggan"}, {"key": "C", "text": "PSAK 16: Aset Tetap"}, {"key": "D", "text": "PSAK 30: Sewa"}]'::jsonb,'C','PSAK 16 (Aset Tetap) adalah standar yang mengatur perlakuan akuntansi untuk aset tetap, mulai dari pengakuan awal (biaya perolehan), pengukuran setelah perolehan (termasuk penyusutan), hingga penghentian dan pelepasan. Aset seperti pembangkit dan jaringan transmisi adalah komponen aset tetap terbesar bagi PLN.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Unit Jasa Konstruksi PLN mendapatkan kontrak khusus untuk membangun gardu induk (substation) sesuai spesifikasi unik pelanggan industri besar. Sistem perhitungan biaya yang paling tepat untuk mengakumulasi biaya proyek kustom ini adalah...','[{"key": "A", "text": "Process Costing"}, {"key": "B", "text": "Job Order Costing"}, {"key": "C", "text": "Activity Based Costing"}, {"key": "D", "text": "Standard Costing"}]'::jsonb,'B','Job Order Costing (Perhitungan Biaya Berdasarkan Pesanan) digunakan ketika produk atau jasa bersifat unik dan dibuat khusus sesuai pesanan pelanggan (heterogen). Biaya (bahan, tenaga kerja, overhead) dikumpulkan untuk setiap "pesanan" (dalam hal ini, proyek gardu induk). Process Costing (digunakan di Paket 2) adalah untuk produk massal dan homogen seperti produksi listrik.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada 2 Januari, PLN membeli sebuah turbin gas baru seharga Rp 50 Miliar. Aset ini memiliki umur ekonomis 5 tahun dan diperkirakan tidak memiliki nilai sisa. Jika PLN menggunakan metode penyusutan Saldo Menurun Ganda (Double Declining Balance), berapakah beban penyusutan untuk tahun pertama?','[{"key": "A", "text": "Rp 10 Miliar"}, {"key": "B", "text": "Rp 20 Miliar"}, {"key": "C", "text": "Rp 15 Miliar"}, {"key": "D", "text": "Rp 5 Miliar"}]'::jsonb,'B',' Tarif Garis Lurus = 1 / Umur Ekonomis = 1 / 5 tahun = 20%. Tarif Saldo Menurun Ganda = 2 * Tarif Garis Lurus = 2 * 20% = 40%. Beban Penyusutan Tahun 1 = Tarif Saldo Menurun Ganda * Nilai Buku Awal
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang mempertimbangkan untuk menjual sebidang tanah non-produktif. Tanah tersebut dapat dijual sekarang seharga Rp 10 Miliar, atau dapat dikembangkan menjadi area Gardu Induk baru yang diperkirakan akan menghemat biaya operasional Rp 2 Miliar per tahun. Dalam konteks keputusan "mengembangkan Gardu Induk", nilai Rp 10 Miliar dari penjualan yang hilang adalah contoh dari...','[{"key": "A", "text": "Sunk Cost"}, {"key": "B", "text": "Opportunity Cost"}, {"key": "C", "text": "Incremental Cost"}, {"key": "D", "text": "Biaya Tetap"}]'::jsonb,'B','Opportunity Cost (Biaya Peluang) adalah nilai manfaat terbaik yang hilang (dikorbankan) ketika memilih satu alternatif di antara beberapa pilihan. Dengan memilih membangun gardu induk, PLN mengorbankan peluang untuk mendapatkan kas Rp 10 Miliar dari penjualan tanah. Sunk Cost (dibahas di Paket 2) adalah biaya masa lalu yang tidak relevan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Akibat kenaikan harga pasar, PLN memutuskan untuk melakukan revaluasi atas aset tanah Gardu Induk Utama. Nilai buku tanah (biaya perolehan) adalah Rp 50 Miliar, dan nilai wajar hasil penilaian appraisal adalah Rp 120 Miliar. Jurnal untuk mencatat revaluasi ini adalah...','[{"key": "A", "text": "Tanah (Debit) Rp 70 M, Laba atas Revaluasi (Kredit) Rp 70 M"}, {"key": "B", "text": "Tanah (Debit) Rp 70 M, Utang Usaha (Kredit) Rp 70 M"}, {"key": "C", "text": "Tanah (Debit) Rp 70 M, Surplus Revaluasi - Ekuitas (Kredit) Rp 70 M"}, {"key": "D", "text": "Surplus Revaluasi (Debit) Rp 70 M, Tanah (Kredit) Rp 70 M"}]'::jsonb,'C','Sesuai PSAK 16, kenaikan nilai aset akibat revaluasi tidak diakui sebagai laba di Laporan Laba Rugi. Sebaliknya, selisih kenaikan (Rp 120 M - Rp 50 M = Rp 70 M) dicatat sebagai penambah nilai Aset Tetap - Tanah (Debit) dan diakui sebagai komponen Ekuitas Lainnya, yaitu ''Surplus Revaluasi'', di sisi Kredit.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah PLTU PLN memiliki biaya tetap bulanan Rp 50 Miliar dan biaya variabel Rp 300 per kWh. Harga jual listrik rata-rata adalah Rp 800 per kWh. Berapa kWh yang harus dijual PLN agar dapat mencapai Target Laba Operasi bulanan sebesar Rp 20 Miliar?','[{"key": "A", "text": "100.000.000 kWh"}, {"key": "B", "text": "140.000.000 kWh"}, {"key": "C", "text": "87.500.000 kWh"}, {"key": "D", "text": "233.333.333 kWh"}]'::jsonb,'B',' Margin Kontribusi per kWh = Harga Jual - Biaya Variabel = Rp 800 - Rp 300 = Rp 500. Rumus Unit Target Laba = (Biaya Tetap + Target Laba) / Margin Kontribusi per Unit
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah unit PLN menjual genset cadangan lama yang sudah tidak terpakai. Biaya perolehan awal genset adalah Rp 500 juta, dan Akumulasi Penyusutan sampai tanggal penjualan adalah Rp 400 juta. Genset tersebut berhasil dijual tunai seharga Rp 120 juta. Hasil dari transaksi ini adalah...','[{"key": "A", "text": "Laba atas Pelepasan Aset Rp 20 juta"}, {"key": "B", "text": "Rugi atas Pelepasan Aset Rp 20 juta"}, {"key": "C", "text": "Laba atas Pelepasan Aset Rp 120 juta"}, {"key": "D", "text": "Rugi atas Pelepasan Aset Rp 380 juta"}]'::jsonb,'A',' Nilai Buku Aset = Biaya Perolehan - Akumulasi Penyusutan
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menggunakan sistem sewa (leasing) untuk kendaraan operasional lapangan selama 5 tahun. Total pembayaran sewa hampir setara dengan harga tunai kendaraan, dan di akhir masa sewa, PLN memiliki opsi untuk membeli kendaraan tersebut dengan harga murah. Sesuai PSAK 30, sewa ini harus diklasifikasikan sebagai...','[{"key": "A", "text": "Sewa Operasi (Operating Lease)"}, {"key": "B", "text": "Sewa Pembiayaan (Finance Lease)"}, {"key": "C", "text": "Sewa Jual-Untung"}, {"key": "D", "text": "Sewa Beli"}]'::jsonb,'B','Sesuai PSAK 30 (sekarang direferensikan ke PSAK 73), jika sewa mengalihkan secara substansial seluruh risiko dan manfaat kepemilikan aset, maka diklasifikasikan sebagai Sewa Pembiayaan. Kriteria seperti masa sewa mencakup sebagian besar umur ekonomis aset, atau adanya opsi beli dengan harga murah, menunjukkan ini adalah Sewa Pembiayaan, di mana PLN (penyewa) harus mengakui Aset Hak Guna dan Liabilitas Sewa di neraca.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Departemen Pemeliharaan Jaringan mencatat data biaya dan jam kerja (Aktivitas) sbb:
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah pelanggan industri besar (Kawasan Industri) menerima pasokan listrik khusus dari PLN dengan harga diskon di bawah tarif normal, namun masih di atas biaya variabel PLN. Pesanan ini tidak mengganggu pasokan reguler. Dalam pengambilan keputusan, biaya yang relevan bagi PLN untuk menerima pesanan ini adalah...','[{"key": "A", "text": "Biaya Tetap Pembangkit"}, {"key": "B", "text": "Biaya Diferensial (Incremental Costs)"}, {"key": "C", "text": "Biaya Penuh (Full Costs)"}, {"key": "D", "text": "Biaya Penyusutan Turbin"}]'::jsonb,'B','Dalam keputusan jangka pendek "menerima atau menolak pesanan khusus", biaya yang relevan adalah biaya diferensial (biaya tambahan yang timbul jika pesanan diterima), yang dalam hal ini adalah biaya variabel. Selama harga jual pesanan khusus dapat menutupi biaya variabel dan memberikan margin kontribusi positif (untuk menutup biaya tetap), pesanan tersebut menguntungkan, asumsi masih ada kapasitas terpasang.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PT PLN (Induk) memiliki piutang usaha kepada anak perusahaannya, PT PJB (Pembangkitan Jawa-Bali), sebesar Rp 50 Miliar atas jasa manajemen. Dalam penyusunan Laporan Keuangan Konsolidasi, jurnal eliminasi yang diperlukan terkait transaksi ini adalah...','[{"key": "A", "text": "Piutang Usaha (Debit) Rp 50 M, Utang Usaha (Kredit) Rp 50 M"}, {"key": "B", "text": "Utang Usaha (Debit) Rp 50 M, Piutang Usaha (Kredit) Rp 50 M"}, {"key": "C", "text": "Kas (Debit) Rp 50 M, Piutang Usaha (Kredit) Rp 50 M"}, {"key": "D", "text": "Tidak perlu jurnal eliminasi"}]'::jsonb,'B','Dalam laporan konsolidasi, PLN dan PJB dianggap sebagai satu entitas tunggal. Utang-piutang antar anggota grup (transaksi antarperusahaan) harus dihapuskan (dieliminasi) agar tidak terjadi perhitungan ganda. Di buku PLN tercatat Piutang Rp 50 M, dan di buku PJB tercatat Utang Rp 50 M. Jurnal eliminasi akan mendebit Utang Usaha (menghapus utang PJB) dan mengkredit Piutang Usaha (menghapus piutang PLN).','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang menghitung Biaya Modal Rata-rata Tertimbang (WACC) untuk mendanai proyek transmisi baru. Data perusahaan adalah sbb:
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Unit operasional PLN memiliki data manajemen modal kerja sbb:
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manajemen PLN sedang mengevaluasi proyek PLTA baru. Mereka menguji NPV proyek dengan tiga skenario: (1) Pesimis: Harga jual listrik rendah & biaya konstruksi tinggi, (2) Realistis, dan (3) Optimis: Harga jual tinggi & biaya konstruksi rendah. Teknik analisis risiko ini disebut...','[{"key": "A", "text": "Analisis Sensitivitas"}, {"key": "B", "text": "Analisis Skenario"}, {"key": "C", "text": "Analisis Monte Carlo"}, {"key": "D", "text": "Analisis Titik Impas (BEP)"}]'::jsonb,'B','Ini adalah Analisis Skenario. Perbedaannya dengan Analisis Sensitivitas (dibahas di Paket 2) adalah: Analisis Sensitivitas: Mengubah hanya SATU variabel (misal: hanya harga jual) untuk melihat dampaknya ke NPV. Analisis Skenario: Mengubah BEBERAPA variabel kunci secara bersamaan (misal: harga jual DAN biaya konstruksi) untuk melihat dampak gabungan dalam kondisi tertentu (pesimis, optimis).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika PLN menginvestasikan kelebihan kas sebesar Rp 100 Miliar hari ini dalam instrumen keuangan yang memberikan imbal hasil 6% per tahun (compounded annually), berapakah nilai investasi tersebut pada akhir tahun ke-5? (Gunakan (1+r)^n di mana r=0,06, n=5 ≈ 1,338)','[{"key": "A", "text": "Rp 130,00 Miliar"}, {"key": "B", "text": "Rp 106,00 Miliar"}, {"key": "C", "text": "Rp 133,80 Miliar"}, {"key": "D", "text": "Rp 74,73 Miliar"}]'::jsonb,'C','Ini adalah perhitungan Nilai Masa Depan (Future Value / FV) dari sejumlah uang saat ini (Present Value). Rumus: FV = PV * (1 + r)^n Perhitungan: Rp 100 Miliar * (1 + 0,06)^5 = Rp 100 Miliar * 1,3382... ≈ Rp 133,8 Miliar.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Struktur modal optimal (Optimal Capital Structure) bagi sebuah perusahaan seperti PLN adalah komposisi utang dan ekuitas yang...','[{"key": "A", "text": "Memaksimalkan penggunaan utang (leverage)"}, {"key": "B", "text": "Menghasilkan Laba Bersih per Saham (EPS) tertinggi"}, {"key": "C", "text": "Meminimalkan Biaya Modal Rata-rata Tertimbang (WACC)"}, {"key": "D", "text": "Menghasilkan rasio DER (Debt to Equity Ratio) sama dengan 1"}]'::jsonb,'C','Tujuan dari manajemen struktur modal adalah menemukan titik di mana kombinasi utang dan ekuitas menghasilkan WACC yang paling rendah. WACC yang rendah berarti biaya pendanaan perusahaan murah, yang pada gilirannya akan memaksimalkan nilai perusahaan (Value of the Firm).','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang mempertimbangkan dua proyek pembangunan Pembangkit Listrik Tenaga Surya (PLTS) baru. Proyek A (di Bali) dan Proyek B (di Sumba). Karena keterbatasan anggaran, PLN hanya dapat memilih salah satu. Dalam terminologi capital budgeting, kedua proyek ini bersifat...','[{"key": "A", "text": "Independent (Independen)"}, {"key": "B", "text": "Mutually Exclusive (Saling Meniadakan)"}, {"key": "C", "text": "Revenue Generating (Menghasilkan Pendapatan)"}, {"key": "D", "text": "Contingent (Bergantung)"}]'::jsonb,'B','Proyek Mutually Exclusive adalah dua atau lebih proyek di mana penerimaan satu proyek akan otomatis meniadakan atau mencegah penerimaan proyek lainnya. Hal ini sering terjadi karena keterbatasan sumber daya (seperti anggaran) atau karena proyek-proyek tersebut melayani fungsi yang sama.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menerbitkan obligasi (surat utang) dengan kupon bunga 10% per tahun. Tarif pajak penghasilan (PPh) badan adalah 22%. Berapakah biaya utang efektif setelah pajak (after-tax cost of debt) dari obligasi tersebut bagi PLN?','[{"key": "A", "text": "10,00%"}, {"key": "B", "text": "12,82%"}, {"key": "C", "text": "2,20%"}, {"key": "D", "text": "7,80%"}]'::jsonb,'D','Bunga utang dapat menjadi pengurang pajak (tax deductible). Rumus: Biaya Utang Setelah Pajak = Biaya Utang Sebelum Pajak * (1 - Tarif Pajak) Perhitungan: 10% * (1 - 0,22) = 10% * 0,78 = 7,80%. Bagi perusahaan, biaya riil dari utang 10% tersebut hanyalah 7,80%.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah proyek PLTU Mini membutuhkan investasi awal Rp 500 Miliar. Proyek ini diperkirakan akan menghasilkan arus kas bersih (net cash flow) yang sama setiap tahunnya, yaitu sebesar Rp 125 Miliar per tahun. Berapakah Payback Period (non-discounted) proyek ini?','[{"key": "A", "text": "3 tahun"}, {"key": "B", "text": "4 tahun"}, {"key": "C", "text": "5 tahun"}, {"key": "D", "text": "0,25 tahun"}]'::jsonb,'B','Payback Period adalah waktu yang dibutuhkan untuk mengembalikan investasi awal. Untuk arus kas yang sama (anuitas): Rumus: Investasi Awal / Arus Kas per Tahun Perhitungan: Rp 500 Miliar / Rp 125 Miliar per tahun = 4 tahun.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah unit PLN memiliki data keuangan sbb:
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika PLN berinvestasi pada proyek Pembangkit Listrik Tenaga Angin (PLTB) dengan Internal Rate of Return (IRR) sebesar 15%, dan WACC (Biaya Modal) PLN adalah 9,69%, keputusan yang harus diambil adalah...','[{"key": "A", "text": "Menerima proyek, karena IRR lebih besar dari WACC"}, {"key": "B", "text": "Menolak proyek, karena IRR lebih kecil dari WACY"}, {"key": "C", "text": "Menerima proyek, karena IRR menghasilkan NPV positif"}, {"key": "D", "text": "Jawaban a dan c benar"}]'::jsonb,'D','Aturan pengambilan keputusan investasi adalah: Proyek diterima jika IRR > WACC (Biaya Modal). Ketika IRR (15%) lebih besar dari tingkat diskonto/WACC (9,69%), ini secara matematis juga berarti bahwa jika proyek didiskontokan dengan WACC tersebut, nilai NPV-nya akan positif. Kedua pernyataan tersebut (a dan c) saling mendukung dan benar.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menyewa sebidang tanah milik warga untuk pembangunan Gardu Induk baru dengan nilai sewa Rp 100.000.000 per tahun. Sesuai ketentuan perpajakan, atas pembayaran sewa tanah tersebut, PLN wajib memotong...','[{"key": "A", "text": "PPh Pasal 23 (Sewa Jasa) sebesar 2%"}, {"key": "B", "text": "PPh Pasal 4 ayat (2) Final (Sewa Tanah/Bangunan) sebesar 10%"}, {"key": "C", "text": "PPh Pasal 21 (untuk pemilik Orang Pribadi)"}, {"key": "D", "text": "PPh Pasal 22 (Pembelian oleh BUMN)"}]'::jsonb,'B','Penghasilan atas sewa tanah dan/atau bangunan merupakan objek PPh Pasal 4 ayat (2) yang bersifat Final. Tarifnya adalah 10% dari nilai sewa. Ini berbeda dengan sewa aset lain (selain tanah/bangunan, misal sewa kendaraan) yang merupakan objek PPh Pasal 23.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN (sebagai Pengusaha Kena Pajak) membeli sebuah transformator baru dari pabrikan senilai Rp 500.000.000 (Dasar Pengenaan Pajak). PPN 11% (Rp 55.000.000) yang dibayar oleh PLN atas pembelian ini, dalam mekanisme PPN, diperlakukan sebagai...','[{"key": "A", "text": "Pajak Keluaran (yang harus disetor ke negara)"}, {"key": "B", "text": "Pajak Masukan (yang dapat dikreditkan/dikurangkan)"}, {"key": "C", "text": "Beban Pajak (langsung mengurangi laba)"}, {"key": "D", "text": "Pajak yang Ditangguhkan"}]'::jsonb,'B','PPN yang dibayar oleh perusahaan saat melakukan pembelian barang/jasa kena pajak (transformator) disebut Pajak Masukan. Karena transformator ini digunakan untuk kegiatan operasional yang menghasilkan penyerahan kena pajak (menjual listrik, yang PPN-nya adalah Pajak Keluaran), maka Pajak Masukan tersebut dapat dikreditkan (mengurangi) jumlah Pajak Keluaran yang harus disetor PLN.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Auditor eksternal (KAP) menemukan bahwa sistem pencatatan persediaan batu bara PLN di satu lokasi PLTU besar tidak memadai dan mereka tidak dapat melakukan stok opname. Masalah ini material, namun tidak merusak laporan keuangan secara keseluruhan. Opini audit yang paling mungkin diberikan adalah...','[{"key": "A", "text": "Wajar Tanpa Pengecualian (Unqualified)"}, {"key": "B", "text": "Wajar Dengan Pengecualian (Qualified)"}, {"key": "C", "text": "Tidak Wajar (Adverse)"}, {"key": "D", "text": "Tidak Memberikan Pendapat (Disclaimer)"}]'::jsonb,'B','Opini WDP (Qualified) diberikan ketika auditor menyimpulkan bahwa laporan keuangan secara umum wajar, TAPI ada satu masalah material (bisa karena pembatasan ruang lingkup/tidak cukup bukti seperti kasus ini, atau penyimpangan PSAK) yang tidak "pervasif" (tidak merusak keseluruhan laporan).','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika auditor eksternal menemukan bahwa manajemen PLN secara sengaja menolak untuk mencatat Beban Penyusutan atas semua aset pembangkitnya (PLTU, PLTA) dengan alasan agar laba terlihat tinggi. Penyimpangan dari PSAK 16 ini sangat material dan berdampak luas (pervasif) ke Neraca dan Laba Rugi. Opini yang harus diberikan adalah...','[{"key": "A", "text": "Wajar Tanpa Pengecualian (Unqualified)"}, {"key": "B", "text": "Wajar Dengan Pengecualian (Qualified)"}, {"key": "C", "text": "Tidak Wajar (Adverse)"}, {"key": "D", "text": "Tidak Memberikan Pendapat (Disclaimer)"}]'::jsonb,'C','Opini Tidak Wajar (Adverse) adalah opini terburuk. Ini diberikan ketika auditor memiliki bukti yang cukup bahwa laporan keuangan secara keseluruhan mengandung salah saji yang sangat material DAN pervasif (menyebar ke banyak akun dan menyesatkan pengguna). Menolak mencatat beban penyusutan adalah pelanggaran fatal terhadap PSAK.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebagai BUMN, PLN wajib mempublikasikan Laporan Keuangan Tahunan yang telah diaudit kepada masyarakat melalui website dan media massa. Praktik ini merupakan implementasi utama dari prinsip Good Corporate Governance (GCG) yaitu...','[{"key": "A", "text": "Akuntabilitas (Accountability)"}, {"key": "B", "text": "Transparansi (Transparency)"}, {"key": "C", "text": "Independensi (Independency)"}, {"key": "D", "text": "Kewajaran (Fairness)"}]'::jsonb,'B','Prinsip Transparansi dalam GCG menuntut perusahaan untuk menyediakan informasi yang material dan relevan (termasuk laporan keuangan) dengan cara yang mudah diakses dan dipahami oleh pemangku kepentingan (publik, investor), sehingga mereka dapat mengambil keputusan yang tepat.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer akuntansi di PLN mendapat tekanan kuat dari atasannya untuk menunda pencatatan biaya pemeliharaan besar (overhaul) ke periode berikutnya agar target laba triwulan ini tercapai. Manajer tersebut menolak karena tidak sesuai fakta. Ia telah menegakkan prinsip etika profesi...','[{"key": "A", "text": "Kompetensi Profesional"}, {"key": "B", "text": "Kerahasiaan (Confidentiality)"}, {"key": "C", "text": "Integritas (Integrity)"}, {"key": "D", "text": "Objektivitas (Objectivity)"}]'::jsonb,'C','Prinsip Integritas menuntut seorang akuntan profesional untuk bersikap jujur, terus terang, dan berani menolak tekanan (tidak tunduk pada kepentingan pribadi atau atasan) yang dapat mengorbankan kebenaran atau menyesatkan laporan keuangan.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang auditor internal PLN baru saja dipindahkan dari Departemen Pengadaan Batu Bara ke Divisi Audit Internal. Tugas pertamanya adalah mengaudit proses pengadaan batu bara. Untuk menjaga etika, ia harus...','[{"key": "A", "text": "Tetap mengaudit, karena dia yang paling paham prosesnya"}, {"key": "B", "text": "Mengungkapkan adanya ancaman objektivitas kepada Kepala Audit Internal"}, {"key": "C", "text": "Melakukan audit tetapi tidak melaporkan temuan negatif"}, {"key": "D", "text": "Menolak tugas dan langsung mengundurkan diri"}]'::jsonb,'B','Prinsip Objektivitas mensyaratkan auditor internal untuk tidak bias dan bebas dari konflik kepentingan. Mengaudit departemen tempat ia baru saja bekerja (ancaman kedekatan atau self-review) dapat mengganggu objektivitas. Langkah yang tepat adalah mengungkapkannya kepada atasan (Kepala Audit) yang akan memutuskan (misalnya dengan menugaskan auditor lain ke tugas tersebut).','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam Laporan Tahunan PLN, terdapat "Surat Pernyataan Direksi" (Statement of Directors'' Responsibility) yang menyatakan bahwa Direksi bertanggung jawab penuh atas penyusunan dan kebenaran isi laporan keuangan. Hal ini merupakan implementasi prinsip GCG...','[{"key": "A", "text": "Transparansi"}, {"key": "B", "text": "Kewajaran"}, {"key": "C", "text": "Independensi"}, {"key": "D", "text": "Akuntabilitas (Accountability)"}]'::jsonb,'D','Prinsip Akuntabilitas adalah pertanggungjawaban. Ini menegaskan bahwa Direksi adalah pihak yang bertanggung jawab (accountable) kepada pemegang saham dan pemangku kepentingan lainnya atas kinerja perusahaan dan kebenaran informasi (termasuk laporan keuangan) yang mereka sajikan.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Auditor internal PLN sering menggunakan kerangka kerja (framework) yang diakui secara global untuk mengevaluasi efektivitas pengendalian internal, yang mencakup 5 komponen (Lingkungan Pengendalian, Penilaian Risiko, Aktivitas Pengendalian, Informasi & Komunikasi, Pemantauan). Kerangka kerja ini dikenal sebagai...','[{"key": "A", "text": "PSAK (Standar Akuntansi Keuangan)"}, {"key": "B", "text": "COSO (Committee of Sponsoring Organizations)"}, {"key": "C", "text": "ISO 9001 (Manajemen Mutu)"}, {"key": "D", "text": "GCG (Good Corporate Governance)"}]'::jsonb,'B','COSO adalah kerangka kerja (framework) yang paling banyak digunakan di dunia untuk merancang, mengimplementasikan, dan mengevaluasi sistem Pengendalian Internal (Internal Control). Hal ini sesuai dengan yang disebutkan dalam kisi-kisi.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menyediakan saluran khusus (telepon, email) di mana karyawan atau masyarakat dapat melaporkan dugaan fraud (kecurangan) atau pelanggaran etika secara anonim dan aman. Sistem pelaporan pelanggaran ini dikenal sebagai...','[{"key": "A", "text": "Audit Investigatif"}, {"key": "B", "text": "COSO Framework"}, {"key": "C", "text": "Manajemen Risiko"}, {"key": "D", "text": "Whistleblowing System"}]'::jsonb,'D','Whistleblowing System (WBS) adalah bagian penting dari implementasi GCG dan mekanisme anti-fraud. Ini adalah mekanisme bagi pelapor (whistleblower) untuk melaporkan pelanggaran secara aman dan anonim, sehingga dapat ditindaklanjuti oleh perusahaan tanpa takut adanya pembalasan.','AKDING',40);
